import{z as r,x as s,o as E,c,q as o,j as l,D as e,d as i,s as d,S as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"LTO","description":"","frontmatter":{"title":"LTO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lto.md","filePath":"cs/lto.md","lastUpdated":1791413859000}'),B={name:"cs/lto.md"};function T(A,a,p,h,L,O){const t=s("Mermaid");return E(),c("div",null,[a[2]||(a[2]=o('<h1 id="lto" tabindex="-1">LTO <a class="header-anchor" href="#lto" aria-label="Permalink to &quot;LTO&quot;">​</a></h1><div class="epigraph"><p>链接期优化把多个编译单元的 IR 放到一起，得到全程序调用图与内联，而不要求源文件合成一份翻译单元。</p><footer>—— 据 Glek and Hubička, Optimizing real-world applications with GCC LTO；LLVM LTO/ThinLTO；龙书过程间优化整理</footer></div><p>上一课<a href="/cs/pgo">PGO</a>给热度，但单 TU 看不见其它 <code>.c</code> 的函数体。缺口是 <strong>LTO</strong>：编译器吐 IR 位码，链接器调优化器再代码生成。ThinLTO：摘要先行、并行后端，减内存。本课钉工作流，不写 ELF 节布局——链接课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 的分别编译使 <code>static</code> 小函数跨文件无法内联，虚调用目标不全。LTO：全程序（或近全）IR。缺口是<strong>何时优化、谁当链接器插件</strong>，不是 PGO 插桩。</p><p>代价：内存、时间、增量编译失效。ThinLTO 用函数摘要+导入热 callee 近似全 LTO。</p><p><span class="marginnote">直觉类比：LTO 像交稿前把全班各章汇成一册通读润色，普通链接只是把各章钉在一起。ThinLTO 则是每人先交一页「章节摘要」，主编按摘要决定谁要参考谁的哪几节，再各自回去改——不必把整本书摊在同一张桌子上。</span></p><h3 id="lto-不是「把-c-都-include-在一起」" tabindex="-1">LTO 不是「把 .c 都 <code>#include</code> 在一起」 <a class="header-anchor" href="#lto-不是「把-c-都-include-在一起」" aria-label="Permalink to &quot;LTO 不是「把 .c 都 `#include` 在一起」&quot;">​</a></h3><p>语言规则仍按 TU 看名字内部链接；LTO 在 IR 级合并。宏与 <code>static</code> 的身份按符号，不是文本粘贴。</p><p><span class="marginnote">GCC LTO。LLVM gold/lld 插件。ThinLTO（Johnson et al.）。本课不写 fat LTO 对象的全部格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>clang -flto</code>：<code>.o</code> 里是 bitcode。<code>lld</code> 调 <code>lto</code>：合并、内联、IPSCCP、DCE 无用全局、再分发后端。与 PGO：先 LTO 插桩或 IR 级轮廓。</p>',12)),(E(),l(n,null,{default:e(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TU%5B%22%E5%90%84%20TU%20%E2%86%92%20IR%22%5D%20--%3E%20LINK%5B%22%E9%93%BE%E6%8E%A5%E5%99%A8%E6%8F%92%E4%BB%B6%22%5D%0A%20%20LINK%20--%3E%20IPO%5B%22%E5%85%A8%E7%A8%8B%E5%BA%8F%E4%BC%98%E5%8C%96%22%5D%0A%20%20IPO%20--%3E%20CG%5B%22%E4%BB%A3%E7%A0%81%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>与<a href="/cs/interprocedural-callgraph">调用图</a>：LTO 才有闭世界（静态链接）。动态库边界仍开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>符号可见性：被其它 <code>.so</code> 用的符号不能删、不能改约定。<code>hidden</code>/<code>internal</code> 使 DCE 更狠。不要 LTO 进不兼容的 IR 版本。</p><p><span class="marginnote">常见误区：初学者以为加上 <code>-flto</code> 就自动全程序优化。只要符号还被其它动态库引用，就不能删不能内联，闭世界假设名存实亡——LTO 的收益大头来自可见性收窄成 <code>hidden</code> 的「内部」符号，导出越多收益越薄。</span></p>',4)),(E(),l(n,null,{default:e(()=>[d(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%85%A8%20LTO%3A%20%E5%85%A8%E9%83%A8%20IR%20%E4%B8%80%E6%AC%A1%E6%80%A7%E5%90%88%E5%B9%B6%22%5D%20--%3E%20PRO%5B%22%E5%86%85%E8%81%94%E4%B8%8E%20DCE%20%E8%A7%86%E9%87%8E%E6%9C%80%E5%85%A8%22%5D%0A%20%20FULL%20--%3E%20COST%5B%22%E5%8D%95%E8%BF%9B%E7%A8%8B%E5%86%85%E5%AD%98%E4%B8%8E%E9%93%BE%E6%8E%A5%E6%97%B6%E9%97%B4%E5%A4%A7%22%5D%0A%20%20THIN%5B%22ThinLTO%20%E4%B8%A4%E9%98%B6%E6%AE%B5%22%5D%20--%3E%20PH1%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%3A%20%E5%B9%B6%E8%A1%8C%E7%94%9F%E6%88%90%E5%87%BD%E6%95%B0%E6%91%98%E8%A6%81%E4%B8%8E%E7%B4%A2%E5%BC%95%22%5D%0A%20%20PH1%20--%3E%20RES%5B%22%E9%93%BE%E6%8E%A5%E6%97%B6%E5%90%88%E5%B9%B6%E7%B4%A2%E5%BC%95%2C%20%E5%86%B3%E5%AE%9A%E8%B7%A8%E6%A8%A1%E5%9D%97%E5%AF%BC%E5%85%A5%22%5D%0A%20%20RES%20--%3E%20PH2%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%3A%20%E5%90%84%E6%A8%A1%E5%9D%97%E5%B9%B6%E8%A1%8C%E4%BC%98%E5%8C%96%E4%B8%8E%E4%BB%A3%E7%A0%81%E7%94%9F%E6%88%90%22%5D%0A%20%20PH2%20--%3E%20THER%5B%22%E6%94%B6%E7%9B%8A%E8%BF%91%E4%BC%BC%E5%85%A8%20LTO%2C%20%E5%BC%80%E9%94%80%E8%BF%91%E6%99%AE%E9%80%9A%E9%93%BE%E6%8E%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>并行：ThinLTO 两阶段，摘要全局，优化仍分片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接脚本。后课默认：跨 TU 内联与 DCE 靠 LTO。下一课 UB：全程序分析更敢删「不可能」路径，风险也更大。</p><p><span class="marginnote">为什么重要：LTO 让全程序分析「更有底气」，一旦源码藏着 UB（有符号溢出、未初始化读），被删的可能正是你以为在工作的代码。开 LTO 前先清掉 UB 警告、跑一遍 sanitizer，收益才不会被调试灾难吃掉。</span></p><p>也不把 LTO 当 Java 的 JIT 全程序（那是运行时）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LTO：链接时优化 IR，补全程序视野。</li><li>ThinLTO 用摘要换可扩展性。</li><li>可见性与 <code>.so</code> 边界限制闭世界。</li><li>出处：Glek and Hubička；LLVM LTO/ThinLTO；对照龙书 IPO。</li></ul>',7))])}const m=r(B,[["render",T]]);export{C as __pageData,m as default};
